have h_prime : 9 ∣ 3740 + n := by
  rw [← h_div];
  exact Nat.divides_of_mul_divides_left 9 2 h_div;
have h_sum : 3740 + n ≡ 0 mod 9 := by
  rw [Nat.mod_eq_of_divides h_prime];
  refl;
have h_mod : 3740 ≡ 3 + 7 + 4 + 0 mod 9 := by
  rw [Nat.mod_add, Nat.mod_add, Nat.mod_add];
  simp [Nat.mod_eq_of_le h₀];
have h_mod_n : n ≡ n mod 9 := by simp;
have h_mod_sum : 3 + 7 + 4 + 0 + n ≡ 0 mod 9 := by
  rw [h_mod, h_mod_n, Nat.mod_add];
  exact h_sum;
have h_sum_eq : 14 + n ≡ 0 mod 9 := by simp [h_mod_sum];
have h_n_mod : n ≡ 4 mod 9 := by
  rw [Nat.mod_eq_of_le h₀];
  have : 14 ≡ 5 mod 9 := by norm_num;
  rw [this, Nat.mod_add];
  have : 5 + n ≡ 0 mod 9 := by rw [h_sum_eq];
  rw [Nat.mod_eq_zero_iff];
  exact Nat.exists_eq_add_mul_of_dvd this;
have h_n_le : n ≤ 9 := h₀;
have h_n_eq : n = 4 := by
  have : ∃ k, n = 4 + 9 * k := by
    rw [h_n_mod];
    exact Nat.exists_eq_add_mul_of_dvd h_n_mod;
  rcases this with ⟨k, rfl⟩;
  have : 4 + 9 * k ≤ 9 := by
    linarith [Nat.mul_le_mul_right k (by norm_num) (by norm_num), h_n_le];
  linarith [k, this];
exact h_n_eq
